// ═══════════════════════════════════════════════════════════════════════════
//  ADDA — friends-only glass chat (full build)
//  Express + Socket.IO · 24-hour disappearing messages · edit / unsend / pin /
//  reply / reactions / voice notes / read receipts / search / push notifications
//  profile photos · themes · admin monitor · Supabase optional
//  Frontend is embedded below so a single server.js is enough to deploy.
// ═══════════════════════════════════════════════════════════════════════════
import express from 'express';
import http from 'http';
import { Server } from 'socket.io';
import multer from 'multer';
import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import webpush from 'web-push';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT = process.env.PORT || 3000;
const TTL_MS = 24 * 60 * 60 * 1000;     // messages live 24 hours
const WARN_MS = 60 * 1000;              // countdown shown in last 60s
const ADMIN_KEY = process.env.ADMIN_KEY || 'shadik-admin';
const MAX_UPLOAD = 25 * 1024 * 1024;    // 25 MB chat media
const MAX_AVATAR = 220 * 1024;          // ~220 KB data-URL profile photo
const MAX_PINS = 5;
const REACTIONS = ['👍', '❤️', '😂', '😮', '😢', '🔥'];

const DATA_DIR = path.join(__dirname, 'data');
const UPLOAD_DIR = path.join(__dirname, 'uploads');
fs.mkdirSync(DATA_DIR, { recursive: true });
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

// ── local persistence helpers ─────────────────────────────────────────────
const load = (f, def) => { try { return JSON.parse(fs.readFileSync(path.join(DATA_DIR, f), 'utf8')); } catch { return def; } };
const save = (f, v) => { try { fs.writeFileSync(path.join(DATA_DIR, f), JSON.stringify(v, null, 2)); } catch (e) { console.error('save', f, e.message); } };

// ── Supabase (optional permanent storage for accounts / blocks / sessions) ─
const SB_URL = (process.env.SUPABASE_URL || '').replace(/\/+$/, '');
const SB_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_KEY || '';
const USE_SB = !!(SB_URL && SB_KEY);
const sbHeaders = { apikey: SB_KEY, Authorization: `Bearer ${SB_KEY}`, 'Content-Type': 'application/json' };
async function sbGet(k) {
  const r = await fetch(`${SB_URL}/rest/v1/adda_kv?k=eq.${encodeURIComponent(k)}&select=v`, { headers: sbHeaders });
  if (!r.ok) throw new Error('Supabase read ' + r.status);
  const rows = await r.json(); return rows[0]?.v ?? null;
}
async function sbSet(k, v) {
  const r = await fetch(`${SB_URL}/rest/v1/adda_kv?on_conflict=k`, {
    method: 'POST', headers: { ...sbHeaders, Prefer: 'resolution=merge-duplicates' },
    body: JSON.stringify({ k, v, updated_at: new Date().toISOString() })
  });
  if (!r.ok) throw new Error('Supabase write ' + r.status + ' ' + (await r.text()).slice(0, 200));
}
function persistUsers()    { if (USE_SB) sbSet('users', users).catch(e => console.error('sb users:', e.message));       else save('users.json', users); }
function persistBlocks()   { if (USE_SB) sbSet('blocks', blocks).catch(e => console.error('sb blocks:', e.message));    else save('blocks.json', blocks); }
function persistSessions() { const arr = [...sessions.entries()]; if (USE_SB) sbSet('sessions', arr).catch(e => console.error('sb sessions:', e.message)); else save('sessions.json', arr); }
function persistPush()     { if (USE_SB) sbSet('pushSubs', pushSubs).catch(e => console.error('sb push:', e.message)); else save('push.json', pushSubs); }
function persistVapid()    { if (USE_SB) sbSet('vapid', vapid).catch(e => console.error('sb vapid:', e.message));    else save('vapid.json', vapid); }
async function initStorage() {
  if (USE_SB) {
    try {
      const [u, b, sess, subs, vp] = await Promise.all([sbGet('users'), sbGet('blocks'), sbGet('sessions'), sbGet('pushSubs'), sbGet('vapid')]);
      users = Array.isArray(u) ? u : [];
      blocks = Array.isArray(b) ? b : [];
      sessions.clear();
      if (Array.isArray(sess)) for (const [t, uid] of sess) sessions.set(t, uid);
      pushSubs = (subs && typeof subs === 'object') ? subs : {};
      vapid = vp || null;
      console.log(`Storage: Supabase connected ✓ (${users.length} users loaded)`);
    } catch (e) { console.error('Supabase init failed, using local JSON:', e.message); }
  } else {
    console.log('Storage: local JSON (set SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY for permanent accounts)');
  }
  if (!vapid) { vapid = webpush.generateVAPIDKeys(); persistVapid(); }
  webpush.setVapidDetails('mailto:admin@adda.chat', vapid.publicKey, vapid.privateKey);
}

let users = load('users.json', []);
let blocks = load('blocks.json', []);
const sessions = new Map();              // token -> userId
let messages = [];                       // in-memory, auto-purged
const pins = new Map();                  // convKey -> [messageId]
const online = new Map();                // userId -> Set(socketId)
let pushSubs = load('push.json', {});    // userId -> [PushSubscription]
let vapid = load('vapid.json', null);

const pub = (u) => ({ id: u.id, username: u.username, name: u.name, emoji: u.emoji, color: u.color, avatar: u.avatar || null, isAdmin: u.isAdmin });
const hashPw = (pw, salt) => crypto.scryptSync(pw, salt, 64).toString('hex');
const dmKey = (a, b) => [a, b].sort().join('__');
const convKey = (m) => m.scope === 'group' ? 'group' : dmKey(m.from, m.to);
const isBlocked = (id) => blocks.includes(id);
const canSee = (m, u) => m.scope === 'group' || m.from === u.id || m.to === u.id;

// Public message shape. Edit history is ONLY included for admins.
function pubMsg(m, forAdmin = false) {
  const o = {
    id: m.id, scope: m.scope, from: m.from, fromName: m.fromName, fromEmoji: m.fromEmoji,
    fromColor: m.fromColor, fromAvatar: m.fromAvatar || null, to: m.to,
    type: m.type, text: m.text, media: m.media, replyTo: m.replyTo || null,
    createdAt: m.createdAt, expiresAt: m.expiresAt,
    edited: !!m.editedAt, reactions: m.reactions || {}, readBy: m.readBy || []
  };
  if (forAdmin) o.editHistory = m.editHistory || [];
  return o;
}

// ── express ───────────────────────────────────────────────────────────────
const app = express();
app.set('trust proxy', true);
app.use(express.json({ limit: '2mb' }));
app.use('/uploads', express.static(UPLOAD_DIR));

