const ICON192 = Buffer.from("", 'base64');
const ICON512 = Buffer.from("", 'base64');
for (const [route, f] of Object.entries(FRONT)) app.get(route, (req, res) => res.type(f.type).send(f.body));
app.get('/icons/icon-192.png', (req, res) => res.type('png').send(ICON192));
app.get('/icons/icon-512.png', (req, res) => res.type('png').send(ICON512));


const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, UPLOAD_DIR),
  filename: (req, file, cb) => cb(null, crypto.randomUUID() + path.extname(file.originalname).slice(0, 12))
});
const upload = multer({
  storage, limits: { fileSize: MAX_UPLOAD },
  fileFilter: (req, file, cb) => {
    if (/^(image|video|audio)\//.test(file.mimetype || '')) cb(null, true);
    else cb(new Error('Only image, video or audio files are allowed'));
  }
});

const authUser = (req) => {
  const token = (req.headers.authorization || '').replace('Bearer ', '');
  const uid = sessions.get(token);
  return users.find(u => u.id === uid) || null;
};

app.get('/healthz', async (req, res) => {
  // When Supabase is configured, this lightweight read also keeps the free
  // Supabase project active (UptimeRobot pings this endpoint every 5 min).
  let db = 'local';
  if (USE_SB) { try { await sbGet('blocks'); db = 'supabase'; } catch (e) { db = 'supabase-error'; } }
  res.json({ ok: true, storage: USE_SB ? 'supabase' : 'local', db, users: users.length, messages: messages.length });
});

app.post('/api/logout', (req, res) => {
  const token = (req.headers.authorization || '').replace('Bearer ', '');
  if (sessions.delete(token)) persistSessions();
  res.json({ ok: true });
});

app.post('/api/register', (req, res) => {
  let { username, name, password, adminKey, emoji, color } = req.body || {};
  username = String(username || '').trim().toLowerCase();
  name = String(name || '').trim();
  password = String(password || '');
  if (!/^[a-z0-9_]{3,20}$/.test(username)) return res.status(400).json({ error: 'Username must be 3-20 chars (a-z, 0-9, _)' });
  if (!name || name.length > 40) return res.status(400).json({ error: 'Name must be 1-40 chars' });
  if (color !== undefined && !/^#[0-9a-fA-F]{6}$/.test(color)) return res.status(400).json({ error: 'Invalid color' });
  if (password.length < 4) return res.status(400).json({ error: 'Password must be at least 4 chars' });
  if (users.some(u => u.username === username)) return res.status(409).json({ error: 'Username already taken' });
  const salt = crypto.randomBytes(16).toString('hex');
  const u = {
    id: crypto.randomUUID(), username, name,
    hash: hashPw(password, salt), salt,
    emoji: String(emoji || '😎').slice(0, 8), color: color || '#7c5cff', avatar: null,
    isAdmin: users.length === 0 || adminKey === ADMIN_KEY,
    createdAt: Date.now()
  };
  users.push(u); persistUsers();
  const token = crypto.randomUUID(); sessions.set(token, u.id); persistSessions();
  res.json({ token, user: pub(u) });
});

app.post('/api/login', (req, res) => {
  const username = String(req.body?.username || '').trim().toLowerCase();
  const password = String(req.body?.password || '');
  const u = users.find(x => x.username === username);
  if (!u || u.hash !== hashPw(password, u.salt)) return res.status(401).json({ error: 'Wrong username or password' });
  if (isBlocked(u.id)) return res.status(403).json({ error: 'This account has been blocked by admin' });
  const token = crypto.randomUUID(); sessions.set(token, u.id); persistSessions();
  res.json({ token, user: pub(u) });
});

app.get('/api/me', (req, res) => {
  const u = authUser(req);
  if (!u) return res.status(401).json({ error: 'Not logged in' });
  res.json({ user: pub(u) });
});

// Update profile: name / emoji / color / avatar (data-URL)
app.post('/api/profile', (req, res) => {
  const u = authUser(req);
  if (!u) return res.status(401).json({ error: 'Not logged in' });
  const { name, emoji, color, avatar } = req.body || {};
  if (name !== undefined) {
    const n = String(name).trim();
    if (!n || n.length > 40) return res.status(400).json({ error: 'Name must be 1-40 chars' });
    u.name = n;
  }
  if (emoji !== undefined) u.emoji = String(emoji).slice(0, 8) || u.emoji;
  if (color !== undefined) {
    if (!/^#[0-9a-fA-F]{6}$/.test(color)) return res.status(400).json({ error: 'Invalid color' });
    u.color = color;
  }
  if (avatar !== undefined) {
    if (avatar === null || avatar === '') u.avatar = null;
    else if (typeof avatar === 'string' && /^data:image\/(png|jpeg|webp);base64,/.test(avatar) && avatar.length <= MAX_AVATAR) u.avatar = avatar;
    else return res.status(400).json({ error: 'Invalid photo (use a small PNG/JPG under 200 KB)' });
  }
  persistUsers();
  io.emit('users', users.map(pub));
  res.json({ user: pub(u) });
});

app.get('/api/push/key', (req, res) => {
  if (!authUser(req)) return res.status(401).json({ error: 'Not logged in' });
  res.json({ publicKey: vapid.publicKey });
});
app.post('/api/push/subscribe', (req, res) => {
  const u = authUser(req);
  if (!u) return res.status(401).json({ error: 'Not logged in' });
  const sub = req.body?.subscription;
  if (!sub || typeof sub.endpoint !== 'string' || !/^https:\/\//.test(sub.endpoint) || sub.endpoint.length > 2048 ||
      !sub.keys || typeof sub.keys.p256dh !== 'string' || typeof sub.keys.auth !== 'string') {
    return res.status(400).json({ error: 'Invalid subscription' });
  }
  const arr = (pushSubs[u.id] || []).filter(x => x.endpoint !== sub.endpoint);
  arr.push(sub); pushSubs[u.id] = arr.slice(-5);
  persistPush(); res.json({ ok: true });
});
app.post('/api/push/unsubscribe', (req, res) => {
  const u = authUser(req);
  if (!u) return res.status(401).json({ error: 'Not logged in' });
  const endpoint = req.body?.endpoint;
  pushSubs[u.id] = (pushSubs[u.id] || []).filter(x => x.endpoint !== endpoint);
  persistPush(); res.json({ ok: true });
});

async function sendPush(m) {
  const targets = m.scope === 'group'
    ? users.filter(x => x.id !== m.from && !isBlocked(x.id))
    : users.filter(x => x.id === m.to && !isBlocked(x.id));
  const preview = m.text ? m.text.slice(0, 120) : (m.type === 'audio' ? '🎤 Voice note' : m.type === 'image' ? '📷 Photo' : m.type === 'video' ? '🎥 Video' : 'New message');
  const body = m.scope === 'group' ? m.fromName + ': ' + preview : preview;
  const payload = JSON.stringify({ title: m.scope === 'group' ? 'Group Adda' : m.fromName, body, scope: m.scope, from: m.from, id: m.id });
  for (const t of targets) {
    for (const sub of (pushSubs[t.id] || [])) {
      try { await webpush.sendNotification(sub, payload, { TTL: 86400 }); }
      catch (e) {
        if (e.statusCode === 404 || e.statusCode === 410) {
          pushSubs[t.id] = (pushSubs[t.id] || []).filter(x => x.endpoint !== sub.endpoint);
          persistPush();
        }
      }
    }
  }
}

app.post('/api/upload', (req, res) => {
  const u = authUser(req);
  if (!u) return res.status(401).json({ error: 'Not logged in' });
  if (isBlocked(u.id)) return res.status(403).json({ error: 'Blocked' });
  upload.single('file')(req, res, (err) => {
    if (err) return res.status(400).json({ error: err.message });
    if (!req.file) return res.status(400).json({ error: 'No file' });
    const mime = req.file.mimetype || '';
    const type = mime.startsWith('video') ? 'video' : mime.startsWith('audio') ? 'audio' : mime.startsWith('image') ? 'image' : 'file';
    res.json({ url: '/uploads/' + req.file.filename, name: req.file.originalname, mime, type, size: req.file.size });
  });
});

// ── socket.io ─────────────────────────────────────────────────────────────
const server = http.createServer(app);
const io = new Server(server, { cors: { origin: '*' }, maxHttpBufferSize: 5 * 1024 * 1024 });

const visibleMessages = (u) => messages.filter(m => m.scope === 'group' || m.from === u.id || m.to === u.id);
const onlineList = () => [...online.keys()];
const audience = (m) => m.scope === 'group' ? io : io.to('user:' + m.from).to('user:' + m.to);
const adminIds = () => users.filter(x => x.isAdmin).map(x => x.id);
function emitAdmin(event, payload) { for (const id of adminIds()) io.to('user:' + id).emit(event, payload); }
function pinList(key) { return (pins.get(key) || []).map(id => messages.find(m => m.id === id)).filter(Boolean).map(m => pubMsg(m)); }
function removePinEverywhere(id) {
  for (const [key, arr] of pins) {
    const n = arr.filter(x => x !== id);
    if (n.length !== arr.length) {
      pins.set(key, n);
      const payload = { key, pins: pinList(key) };
      if (key === 'group') io.emit('pins:update', payload);
      else { const [a, b] = key.split('__'); io.to('user:' + a).to('user:' + b).emit('pins:update', payload); }
    }
  }
}

io.use((socket, next) => {
  const uid = sessions.get(socket.handshake.auth?.token);
  const u = users.find(x => x.id === uid);
  if (!u || isBlocked(u.id)) return next(new Error('unauthorized'));
  socket.data.user = u;
  next();
});

io.on('connection', (socket) => {
  const u = socket.data.user;
  if (!online.has(u.id)) online.set(u.id, new Set());
  online.get(u.id).add(socket.id);
  socket.join('user:' + u.id);

  socket.emit('init', {
    me: pub(u), users: users.map(pub),
    messages: visibleMessages(u).map(m => pubMsg(m)),
    pins: { group: pinList('group') },
    blocks: u.isAdmin ? blocks : [], online: onlineList(),
    ttlMs: TTL_MS, warnMs: WARN_MS, reactions: REACTIONS
  });
  io.emit('online', onlineList());
  io.emit('users', users.map(pub));

  socket.on('chat:send', (payload, ack) => {
    try {
      if (isBlocked(u.id)) return ack?.({ error: 'blocked' });
      const { scope, to, type, text, media, replyTo } = payload || {};
      if (scope !== 'group' && scope !== 'dm') return ack?.({ error: 'bad scope' });
      if (scope === 'dm' && !users.some(x => x.id === to)) return ack?.({ error: 'bad recipient' });
      const msgType = type || 'text';
      if (!['text', 'image', 'video', 'audio'].includes(msgType)) return ack?.({ error: 'bad type' });
      if (msgType !== 'text' && !media) return ack?.({ error: 'media required' });
      if (media && (!media.url || !String(media.url).startsWith('/uploads/'))) return ack?.({ error: 'bad media' });
      const cleanText = String(text || '').slice(0, 4000);
      if (msgType === 'text' && !cleanText.trim() && !media) return ack?.({ error: 'empty' });
      let reply = null;
      if (replyTo) {
        const orig = messages.find(m => m.id === replyTo);
        if (orig && canSee(orig, u)) reply = { id: orig.id, name: orig.fromName, snippet: (orig.text || (orig.media ? '📎 ' + orig.type : '')).slice(0, 120) };
      }
      const m = {
        id: crypto.randomUUID(), scope, from: u.id, fromName: u.name, fromEmoji: u.emoji,
        fromColor: u.color, fromAvatar: u.avatar || null, to: scope === 'dm' ? to : null,
        type: msgType, text: cleanText, media: media || null, replyTo: reply,
        createdAt: Date.now(), expiresAt: Date.now() + TTL_MS, editedAt: null, editHistory: [], reactions: {}, readBy: [u.id]
      };
      messages.push(m);
      audience(m).emit('message:new', pubMsg(m));
      emitAdmin('admin:message', pubMsg(m, true));
      sendPush(m).catch(() => {});
      ack?.({ ok: true, id: m.id });
    } catch (e) { ack?.({ error: e.message }); }
  });

  socket.on('message:edit', (p, ack) => {
    const m = messages.find(x => x.id === p?.id);
    if (!m) return ack?.({ error: 'Message not found (maybe expired)' });
    if (m.from !== u.id) return ack?.({ error: 'You can only edit your own messages' });
    const text = String(p.text || '').slice(0, 4000);
    if (!text.trim()) return ack?.({ error: 'Message cannot be empty' });
    if (text === m.text) return ack?.({ ok: true, unchanged: true });
    m.editHistory = [...(m.editHistory || []), { text: m.text, at: Date.now() }].slice(-20);
    m.text = text; m.editedAt = Date.now();
    audience(m).emit('message:edited', pubMsg(m));
    emitAdmin('admin:message-edited', pubMsg(m, true));
    ack?.({ ok: true });
  });

  socket.on('message:unsend', (p, ack) => {
    const idx = messages.findIndex(m => m.id === p?.id);
    if (idx < 0) return ack?.({ error: 'Message not found (maybe expired)' });
    const m = messages[idx];
    if (m.from !== u.id && !u.isAdmin) return ack?.({ error: 'You can only unsend your own messages' });
    messages.splice(idx, 1);
    if (m.media?.url?.startsWith('/uploads/')) fs.unlink(path.join(UPLOAD_DIR, path.basename(m.media.url)), () => {});
    removePinEverywhere(m.id);
    audience(m).emit('message:unsent', { id: m.id, by: u.id });
    emitAdmin('admin:message-unsent', { id: m.id, by: u.id });
    ack?.({ ok: true });
  });

  socket.on('message:react', (p, ack) => {
    const m = messages.find(x => x.id === p?.id);
    const emoji = p?.emoji;
    if (!m || !canSee(m, u) || !REACTIONS.includes(emoji)) return ack?.({ error: 'bad reaction' });
    m.reactions = m.reactions || {};
    const arr = new Set(m.reactions[emoji] || []);
    arr.has(u.id) ? arr.delete(u.id) : arr.add(u.id);
    if (arr.size) m.reactions[emoji] = [...arr]; else delete m.reactions[emoji];
    audience(m).emit('message:reaction', { id: m.id, reactions: m.reactions });
    ack?.({ ok: true });
  });

  socket.on('message:pin', (p, ack) => {
    const m = messages.find(x => x.id === p?.id);
    if (!m || !canSee(m, u)) return ack?.({ error: 'Message not found' });
    const key = convKey(m);
    let arr = pins.get(key) || [];
    if (p.unpin) arr = arr.filter(x => x !== m.id);
    else {
      if (arr.includes(m.id)) return ack?.({ ok: true });
      if (arr.length >= MAX_PINS) return ack?.({ error: `Max ${MAX_PINS} pinned messages` });
      arr = [m.id, ...arr];
    }
    pins.set(key, arr);
    const payload = { key, pins: pinList(key) };
    if (m.scope === 'group') io.emit('pins:update', payload);
    else { io.to('user:' + m.from).to('user:' + m.to).emit('pins:update', payload); }
    ack?.({ ok: true });
  });

  socket.on('pins:get', (p, ack) => {
    const key = p?.scope === 'dm' && p?.to ? dmKey(u.id, p.to) : 'group';
    ack?.({ key, pins: pinList(key) });
  });

  socket.on('chat:read', (p, ack) => {
    const scope = p?.scope === 'dm' ? 'dm' : 'group';
    const to = scope === 'dm' ? p?.to : null;
    if (scope === 'dm' && !users.some(x => x.id === to)) return ack?.({ error: 'bad recipient' });
    const key = scope === 'group' ? 'group' : dmKey(u.id, to);
    const changed = [];
    for (const m of messages) {
      if (m.scope !== scope) continue;
      if (scope === 'dm' && dmKey(m.from, m.to) !== key) continue;
      if (m.from === u.id) continue;
      m.readBy = m.readBy || [];
      if (!m.readBy.includes(u.id)) { m.readBy.push(u.id); changed.push(m.id); }
    }
    if (changed.length) {
      const evt = { key, ids: changed, userId: u.id };
      if (scope === 'group') io.emit('message:read-update', evt);
      else io.to('user:' + u.id).to('user:' + to).emit('message:read-update', evt);
    }
    ack?.({ ok: true, count: changed.length });
  });

  socket.on('typing', (p) => {
    const { scope, to } = p || {};
    const evt = { from: u.id, name: u.name, scope };
    if (scope === 'group') socket.broadcast.emit('typing', evt);
    else if (to) io.to('user:' + to).emit('typing', evt);
  });

  socket.on('dm:history', (p, ack) => {
    const other = p?.userId;
    const list = messages.filter(m => m.scope === 'dm' && dmKey(m.from, m.to) === dmKey(u.id, other));
    ack?.({ messages: list.map(m => pubMsg(m)) });
  });

  socket.on('admin:data', (ack) => {
    if (!u.isAdmin) return ack?.({ error: 'not admin' });
    ack?.({ messages: messages.map(m => pubMsg(m, true)), users: users.map(pub), blocks, online: onlineList() });
  });

  socket.on('admin:block', (p, ack) => {
    if (!u.isAdmin) return ack?.({ error: 'not admin' });
    const { userId, blocked } = p || {};
    const target = users.find(x => x.id === userId);
    if (!target) return ack?.({ error: 'no user' });
    if (target.isAdmin) return ack?.({ error: 'cannot block admin' });
    if (blocked && !blocks.includes(userId)) blocks.push(userId);
    if (!blocked) blocks = blocks.filter(b => b !== userId);
    persistBlocks();
    io.emit('blocks', blocks);
    if (blocked) { const socks = online.get(userId); if (socks) for (const sid of socks) io.sockets.sockets.get(sid)?.disconnect(true); }
    ack?.({ ok: true, blocks });
  });

  socket.on('disconnect', () => {
    const set = online.get(u.id);
    if (set) { set.delete(socket.id); if (set.size === 0) online.delete(u.id); }
    io.emit('online', onlineList());
  });
});

// ── purge expired messages + files ────────────────────────────────────────
setInterval(() => {
  const now = Date.now();
  const expired = messages.filter(m => m.expiresAt <= now);
  if (!expired.length) return;
  messages = messages.filter(m => m.expiresAt > now);
  for (const m of expired) {
    if (m.media?.url?.startsWith('/uploads/')) fs.unlink(path.join(UPLOAD_DIR, path.basename(m.media.url)), () => {});
    removePinEverywhere(m.id);
  }
  io.emit('message:expired', expired.map(m => m.id));
}, 5000);

await initStorage();

server.listen(PORT, '0.0.0.0', () => {
  console.log(`ADDA chat running on http://0.0.0.0:${PORT}`);
  console.log(`Admin key: ${ADMIN_KEY}  (first registered user is also admin)`);
});
